/* Minimal jQuery stub for offline demo: only $(fn) ready */
(function(w){
  function ready(fn){ if(document.readyState!='loading'){ fn(); } else { document.addEventListener('DOMContentLoaded', fn); } }
  function $(arg){ if (typeof arg === 'function') { ready(arg); return; } return document.querySelectorAll(arg); }
  w.$ = w.jQuery = $;
})(window);

